entries[35701] = { ["name"] = "Berührung des Schattens", ["text"] = "100 Meter Reichweite\nSofort\nBei Aktivierung wird Euer beschworener Begleiter geopfert, um Euch einen Effekt zu gewähren, der 30 Min. lang anhält. Der Effekt wird abgebrochen, wenn ein Dämon beschworen wird.\n\nWichtel: Erhöht Euren Feuerschaden um 10%.\n\nLeerwandler: Stellt alle 4 Sek. 2% Eurer gesamten Gesundheit wieder her.\n\nSukkubus: Erhöht Euren Schattenschaden um 10%.\n\nTeufelsjäger: Stellt alle 4 Sek. 3% Eures gesamten Manas wieder her.\n\nTeufelswache: Erhöht Euren Schatten- und Feuerschaden um 7% und stellt alle 4 Sek. 2% Eures gesamten Manas wieder her." }
entries[35702] = { ["name"] = "Meister der Dämonologie", ["text"] = "Sofort\nGewährt Hexenmeister und beschworenem Dämon einen Effekt, solange dieser Dämon aktiv ist.\n\nWichtel - Erhöht Euren Feuerschaden um 1% und erhöht Eure kritische Trefferchance mit Feuerzaubern um 1%.\n\nLeerwandler - Verringert erlittenen körperlichen Schaden um 2%.\n\nSukkubus - Erhöht Euren Schattenschaden um 1% und erhöht Eure kritische Trefferchance mit Schattenzaubern um 1%.\n\nTeufelsjäger - Verringert jeglichen erlittenen Zauberschaden um 2%.\n\nTeufelswache - Erhöht jeglichen verursachten Schaden um 1% und verringert jeglichen erlittenen Schaden um 1%." }
entries[35703] = { ["name"] = "Meister der Dämonologie", ["text"] = "Sofort\nGewährt Hexenmeister und beschworenem Dämon einen Effekt, solange dieser Dämon aktiv ist.\n\nWichtel - Erhöht Euren Feuerschaden um 2% und erhöht Eure kritische Trefferchance mit Feuerzaubern um 2%.\n\nLeerwandler - Verringert erlittenen körperlichen Schaden um 4%.\n\nSukkubus - Erhöht Euren Schattenschaden um 2% und erhöht Eure kritische Trefferchance mit Schattenzaubern um 2%.\n\nTeufelsjäger - Verringert jeglichen erlittenen Zauberschaden um 4%.\n\nTeufelswache - Erhöht jeglichen verursachten Schaden um 2% und verringert jeglichen erlittenen Schaden um 2%." }
entries[35704] = { ["name"] = "Meister der Dämonologie", ["text"] = "Sofort\nGewährt Hexenmeister und beschworenem Dämon einen Effekt, solange dieser Dämon aktiv ist.\n\nWichtel - Erhöht Euren Feuerschaden um 3% und erhöht Eure kritische Trefferchance mit Feuerzaubern um 3%.\n\nLeerwandler - Verringert erlittenen körperlichen Schaden um 6%.\n\nSukkubus - Erhöht Euren Schattenschaden um 3% und erhöht Eure kritische Trefferchance mit Schattenzaubern um 3%.\n\nTeufelsjäger - Verringert jeglichen erlittenen Zauberschaden um 6%.\n\nTeufelswache - Erhöht jeglichen verursachten Schaden um 3% und verringert jeglichen erlittenen Schaden um 3%." }
